import{_ as t,o,c as s,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const k=JSON.parse('{"title":"Tenant API v1 — Projects","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Projects | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-projects"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Projects | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-projects"}]]},"headers":[],"relativePath":"api/tenant-v1-projects.md","filePath":"api/tenant-v1-projects.md","lastUpdated":1787697408000}'),d={name:"api/tenant-v1-projects.md"};function i(c,e,n,r,p,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-projects" tabindex="-1">Tenant API v1 — Projects <a class="header-anchor" href="#tenant-api-v1-—-projects" aria-label="Permalink to &quot;Tenant API v1 — Projects&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:projects</code>, plus permission middleware / policies.</p><p>No hard <code>module_dependencies</code> — Projects installs standalone. <code>contact_id</code>, <code>company_id</code>, and <code>opportunity_id</code> are optional; supplying any requires the corresponding module to be entitled (soft link rules).</p><p>Visibility without <code>projects.assign</code> (and not superadmin): list/board/stats/view/update only include projects where the actor is <strong>assignee</strong>, <strong>member</strong>, or <strong>creator</strong>. With <code>projects.assign</code>, org-wide (<code>scope: org</code> on stats).</p><p>Field name is <strong><code>title</code></strong> (not <code>name</code>).</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-projects-stats" tabindex="-1">GET <code>/projects/stats</code> <a class="header-anchor" href="#get-projects-stats" aria-label="Permalink to &quot;GET `/projects/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_projects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_projects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;planned&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;active&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;active_projects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;on_hold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;completed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cancelled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overdue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overdue_projects&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>active</code> / <code>active_projects</code> are the same count. <code>overdue</code> / <code>overdue_projects</code> count open projects (<code>planned</code>|<code>active</code>|<code>on_hold</code>) whose <code>ends_on</code> is before workspace-local today.</p><h2 id="board" tabindex="-1">Board <a class="header-anchor" href="#board" aria-label="Permalink to &quot;Board&quot;">​</a></h2><h3 id="get-projects-board" tabindex="-1">GET <code>/projects/board</code> <a class="header-anchor" href="#get-projects-board" aria-label="Permalink to &quot;GET `/projects/board`&quot;">​</a></h3><p>One column per status (<code>planned</code>, <code>active</code>, <code>on_hold</code>, <code>completed</code>, <code>cancelled</code>): <code>status</code>, <code>project_count</code>, <code>projects[]</code>. Honors the same filters as list. Optional <code>per_column</code> (1–100, default 50).</p><h2 id="projects-crud" tabindex="-1">Projects CRUD <a class="header-anchor" href="#projects-crud" aria-label="Permalink to &quot;Projects CRUD&quot;">​</a></h2><h3 id="get-projects" tabindex="-1">GET <code>/projects</code> <a class="header-anchor" href="#get-projects" aria-label="Permalink to &quot;GET `/projects`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code>), <code>status</code>, <code>contact_id</code>, <code>company_id</code>, <code>opportunity_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_projects</code>, <code>overdue</code> (open statuses with <code>ends_on</code> before workspace-local today), <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>title</code>, <code>status</code>, <code>description</code>, <code>starts_on</code>, <code>ends_on</code>, soft CRM refs, assignee/creator, <code>members[]</code>, and <code>latest_note</code>.</p><h3 id="post-projects" tabindex="-1">POST <code>/projects</code> <a class="header-anchor" href="#post-projects" aria-label="Permalink to &quot;POST `/projects`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>description</code>, <code>contact_id</code>, <code>company_id</code>, <code>opportunity_id</code>, <code>starts_on</code>, <code>ends_on</code> (<code>after_or_equal:starts_on</code>), <code>assigned_to</code>, <code>member_ids[]</code>.</p><p>Status always starts at <code>planned</code>. Without <code>projects.assign</code>, <code>assigned_to</code> / <code>member_ids</code> are ignored and the creator becomes the assignee. Assignee ids are stripped from <code>member_ids</code>.</p><h3 id="get-projects-id" tabindex="-1">GET <code>/projects/{id}</code> <a class="header-anchor" href="#get-projects-id" aria-label="Permalink to &quot;GET `/projects/{id}`&quot;">​</a></h3><p>Includes contact, company, opportunity, assignee, creator, members, notes, and timeline activities. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="put-projects-id" tabindex="-1">PUT <code>/projects/{id}</code> <a class="header-anchor" href="#put-projects-id" aria-label="Permalink to &quot;PUT `/projects/{id}`&quot;">​</a></h3><p>Partial update of content fields (<code>title</code>, <code>description</code>, soft links, dates, and — with <code>projects.assign</code> — <code>assigned_to</code> / <code>member_ids</code>). Status changes use <code>POST /projects/{id}/status</code>.</p><h3 id="delete-projects-id" tabindex="-1">DELETE <code>/projects/{id}</code> <a class="header-anchor" href="#delete-projects-id" aria-label="Permalink to &quot;DELETE `/projects/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>projects.delete</code>.</p><h3 id="post-projects-id-restore" tabindex="-1">POST <code>/projects/{id}/restore</code> <a class="header-anchor" href="#post-projects-id-restore" aria-label="Permalink to &quot;POST `/projects/{id}/restore`&quot;">​</a></h3><p>Permission: <code>projects.restore</code>.</p><h3 id="delete-projects-id-force" tabindex="-1">DELETE <code>/projects/{id}/force</code> <a class="header-anchor" href="#delete-projects-id-force" aria-label="Permalink to &quot;DELETE `/projects/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted project. Permission: <code>projects.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-projects-id-assign" tabindex="-1">POST <code>/projects/{id}/assign</code> <a class="header-anchor" href="#post-projects-id-assign" aria-label="Permalink to &quot;POST `/projects/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>projects.assign</code>. Detaches the new assignee from members if present.</p><h3 id="put-projects-id-members" tabindex="-1">PUT <code>/projects/{id}/members</code> <a class="header-anchor" href="#put-projects-id-members" aria-label="Permalink to &quot;PUT `/projects/{id}/members`&quot;">​</a></h3><p><code>{ &quot;member_ids&quot;: number[] }</code></p><p>Permission: <code>projects.assign</code>. Full sync; assignee is never stored as a member.</p><h3 id="post-projects-id-status" tabindex="-1">POST <code>/projects/{id}/status</code> <a class="header-anchor" href="#post-projects-id-status" aria-label="Permalink to &quot;POST `/projects/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;planned&quot;|&quot;active&quot;|&quot;on_hold&quot;|&quot;completed&quot;|&quot;cancelled&quot; }</code></p><p>Permission: <code>projects.update</code>. Allowed transitions:</p><table tabindex="0"><thead><tr><th>From</th><th>To</th></tr></thead><tbody><tr><td><code>planned</code></td><td><code>active</code>, <code>cancelled</code></td></tr><tr><td><code>active</code></td><td><code>on_hold</code>, <code>completed</code>, <code>cancelled</code></td></tr><tr><td><code>on_hold</code></td><td><code>active</code>, <code>cancelled</code></td></tr><tr><td><code>completed</code> / <code>cancelled</code></td><td><em>(none)</em></td></tr></tbody></table><p>Rejects disallowed transitions with a 422 validation error on <code>status</code>.</p><h3 id="post-projects-id-notes" tabindex="-1">POST <code>/projects/{id}/notes</code> <a class="header-anchor" href="#post-projects-id-notes" aria-label="Permalink to &quot;POST `/projects/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>projects.update</code>.</p><h3 id="get-projects-id-timeline" tabindex="-1">GET <code>/projects/{id}/timeline</code> <a class="header-anchor" href="#get-projects-id-timeline" aria-label="Permalink to &quot;GET `/projects/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>members_synced</code>, <code>status_changed</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p><h2 id="related-tasks-project-id" tabindex="-1">Related: Tasks <code>project_id</code> <a class="header-anchor" href="#related-tasks-project-id" aria-label="Permalink to &quot;Related: Tasks `project_id`&quot;">​</a></h2><h3 id="soft-link-on-tasks" tabindex="-1">Soft link on Tasks <a class="header-anchor" href="#soft-link-on-tasks" aria-label="Permalink to &quot;Soft link on Tasks&quot;">​</a></h3><p>When creating or updating a task, optional <code>project_id</code> is validated by <code>LinkableProject</code> (Projects module entitled + project visible to the actor). Response embeds <code>project</code> (<code>id</code>, <code>uuid</code>, <code>title</code>, <code>status</code>) when loaded. Documented under <a href="/api/tenant-v1-tasks">Tenant Tasks</a>.</p><h2 id="dashboard-widgets" tabindex="-1">Dashboard widgets <a class="header-anchor" href="#dashboard-widgets" aria-label="Permalink to &quot;Dashboard widgets&quot;">​</a></h2><p>When Projects is entitled and the actor has <code>projects.view</code>, <code>GET /dashboard</code> may include:</p><table tabindex="0"><thead><tr><th>id</th><th>Notes</th></tr></thead><tbody><tr><td><code>active_projects</code></td><td>Active-status rows + <code>total_count</code>; visibility-scoped</td></tr><tr><td><code>overdue_projects</code></td><td>Open + <code>ends_on</code> before workspace today; visibility-scoped</td></tr></tbody></table><p>See <a href="/api/tenant-v1-dashboard">Tenant Dashboard</a>.</p>',55)])])}const u=t(d,[["render",i]]);export{k as __pageData,u as default};
